  "repair_strategy": "Add an early guard in checkFocusIn to clear the mostRecentlyFocusedNode if it is no longer attached to the document, ensuring the recovery logic falls back to the initial focus node or first tabbable element.",
  "edits": [
    {
      "path": "index.js",
      "sha256": "17ff10072d68a0aabb1e15fdc42b3a1dee1774dc2ced6facc4753e9a5ae89f90",
      "before": "  const checkFocusIn = function (event) {\n    const target = getActualTarget(event);\n    const targetContained = findContainerIndex(target, event) >= 0;\n\n    // In Firefox when you Tab out of an iframe the Document is briefly focused.",
      "after": "  const checkFocusIn = function (event) {\n    const target = getActualTarget(event);\n    const targetContained = findContainerIndex(target, event) >= 0;\n\n    // If the MRU node is no longer attached, clear it.\n    if (state.mostRecentlyFocusedNode && !doc.contains(state.mostRecentlyFocusedNode)) {\n      state.mostRecentlyFocusedNode = null;\n    }\n\n    // In Firefox when you Tab out of an iframe the Document is briefly focused."
    }
  ],
  "expected_accessibility_effect": "Keyboard focus remains trapped inside the dialog after removing an item, preserving tab order and preventing focus loss to background elements.",
  "functional_risks": [
    "Clearing the MRU node may cause an extra focus adjustment when a detached node is referenced, but this should not affect normal trap operation."
  ],
  "verification_requirements": [
    "After pressing Enter on the remove button of an item, the count updates and focus stays inside the basket (#basket:focus-within is true).",
    "Tab navigation continues to wrap correctly within the dialog after item removal."
  ]
}

